inputs.where:
@equals(if(
  equals(
    toLower(split(triggerBody()?['{Name}'], '-')[0]),
    'land'
  ),
  and(
    empty(string(item()?['Price']?['Total'])),
    empty(string(item()?['Price']?['Per SF']))
  ),
  and(
    empty(string(item()?['Sale']?['Price'])),
    empty(string(item()?['Sale']?['Price/SF'])),
    empty(string(item()?['Sale']?['Price/Unit']))
  )
),true)

@contains(if(
  equals(
    toLower(split(triggerBody()?['{Name}'], '-')[0]),
    'land'
  ),
  toLower(string(item()?['Sale Date'])),
  toLower(string(item()?['Sale']?['Sale Date']))
),'under contract')

Property_Size.inputs:
@if(
  empty(
    string(body('Sale_Comps_Data')?['Property']?['Property Size (SF)'])
  ),
  if(
    empty(
      string(
        body('Sale_Comps_Data')?['Property']?['RBA (SF)']
      )
    ),
    if(
      empty(
        string(
          body('Sale_Comps_Data')?['Property']?['Gross Leasable Area (SF)']
        )
      ),
      body('Sale_Comps_Data')?['Property']?['Land (SF)'],
      body('Sale_Comps_Data')?['Property']?['Gross Leasable Area (SF)']
    ),
    body('Sale_Comps_Data')?['Property']?['RBA (SF)']
  ),
  body('Sale_Comps_Data')?['Property']?['Property Size (SF)']
)

Price_for_Size.inputs:
@if(
  and(
    not(empty(string(outputs('Property_Size')))),
    not(empty(string(body('Sale_Comps_Data')?['Sale Comps']?['Avg. Price/SF'])))
  ),
  mul(
    outputs('Property_Size'),
    body('Sale_Comps_Data')?['Sale Comps']?['Avg. Price/SF']
  ),
  if(
    and(
      not(empty(string(first(body('Get_Property_Details')?['value'])?['LotSizeAcres']))),
      not(empty(string(body('Sale_Comps_Data')?['Property']?['Sale Price Per AC'])))
    ),
    mul(
      first(body('Get_Property_Details')?['value'])?['LotSizeAcres'],
      body('Sale_Comps_Data')?['Property']?['Sale Price Per AC']
    ),
    null
  )
)

Price_for_Units.inputs:
@if(
  and(
    not(empty(string(body('Sale_Comps_Data')?['Property']?['No. of Units']))),
    not(empty(string(body('Sale_Comps_Data')?['Sale Comps']?['Avg. Price/Unit (thous.)'])))
  ),
  mul(
    body('Sale_Comps_Data')?['Property']?['No. of Units'],
    mul(
      body('Sale_Comps_Data')?['Sale Comps']?['Avg. Price/Unit (thous.)'],
      1000
    )
  ),
  null
)

LTV_Pct.inputs:
@if(
  not(empty(string(first(body('Get_Property_Details')?['value'])?['FirstLoanAmount']))),
  if(
    empty(string(outputs('Price_for_Units'))),
    if(
      empty(string(outputs('Price_for_Size'))),
      null,
      if(
        and(
          greater(
            first(body('Get_Property_Details')?['value'])?['FirstLoanAmount'],
            0
          ),
          greater(
            outputs('Price_for_Size'),
            0
          )
        ),
        div(
          first(body('Get_Property_Details')?['value'])?['FirstLoanAmount'],
          outputs('Price_for_Size')
        ),
        null
      )
    ),
    if(
      and(
        greater(
          first(body('Get_Property_Details')?['value'])?['FirstLoanAmount'],
          0
        ),
        greater(
          outputs('Price_for_Units'),
          0
        )
      ),
      div(
        first(body('Get_Property_Details')?['value'])?['FirstLoanAmount'],
        outputs('Price_for_Units')
      ),
      null
    )
  ),
  null
)

